pub(crate) fn power_meter_manifest() -> IndicatorManifest {
    IndicatorManifest { id: "power-meter", topic_id: "power.status", order: 50, title: "Power Consumption", icon_id: "bolt", initial_state: "loading", admin_interactive: false, render_indicator: render_power_meter_indicator, render_modal: render_power_meter_modal, collector: Some(power_meter_collector) }
}

fn render_power_meter_indicator(ctx: IndicatorRenderContext) -> String { let _ = ctx.session; r##"<button type="button" class="indicator power-indicator" data-indicator="power-meter" data-modal-kind="power-meter" data-modal-title="Power Consumption" aria-label="Measuring Power Usage" title="Measuring power usage"><svg class="indicator-icon" data-packed-icon="bolt" viewBox="0 0 24 24" aria-hidden="true"><path d="M13 2 4 14h7l-1 8 10-13h-7l1-7z"/></svg><span class="power-value-small" data-power-indicator-value><span class="power-value-small-number">—</span><span class="power-value-small-unit">W</span></span></button>"##.to_string() }
fn render_power_meter_modal(ctx: IndicatorRenderContext) -> String { let _ = ctx.session; r##"<div class="power-meter-modal" data-modal-kind-body="power-meter"><div class="power-usage-display"><div class="power-value"><span class="power-value-number">Loading power…</span><span class="power-value-unit">Watts</span></div></div><div class="power-history-section"><div class="power-averages"><div class="power-average-row"><div class="power-average-label">5s average:</div><div class="power-average-value" data-power-average="5">—W</div></div><div class="power-average-row"><div class="power-average-label">30s average:</div><div class="power-average-value" data-power-average="30">—W</div></div><div class="power-average-row"><div class="power-average-label">60s average:</div><div class="power-average-value" data-power-average="60">—W</div></div></div><div class="power-graph-container"><canvas data-power-chart aria-label="Power usage over time"></canvas></div></div></div>"##.to_string() }
fn power_meter_collector(session: Session) -> Result<serde_json::Value, String> { collect_indicator_topic("power.status", session) }
